});

test('vatSummary groups by VAT rate', () => {
  let inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'STICKER', qty: 100 }, // 21% VAT
      { sku: 'BOOK', qty: 50 }, // 9% VAT
    ],
  });
  inv = issueInvoice(inv.value, []).value;

  const result = vatSummary([inv]);
  assert.equal(result.length, 2);

  // Should be sorted by rate descending: 21, then 9
  assert.equal(result[0].rate, 21);
  assert.equal(result[1].rate, 9);
});

test('vatSummary sorts by rate descending (21, 9, 0)', () => {
  let inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [
      { sku: 'STICKER', qty: 100 }, // 21%
      { sku: 'BOOK', qty: 50 }, // 9%
