    customerId: 'C-002',
    issueDate: '2024-10-15',
    lines: [{ sku: 'STICKER', qty: 100 }],
  });
  inv1 = issueInvoice(inv1.value, []).value;

  let inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-10-20',
    lines: [{ sku: 'STICKER', qty: 100, discountPercent: 50 }],
  });
  inv2 = issueInvoice(inv2.value, []).value;

  const result1 = vatSummary([inv1]);
  const result2 = vatSummary([inv2]);

  // Discount reduces the base
  assert.ok(result2[0].base < result1[0].base);
  // Discount reduces the VAT (since VAT is on base after discount)
  assert.ok(result2[0].vat < result1[0].vat);
});

